// The form's answers arrive keyed by the question text, so the labels below
// must match the form exactly. Change a question, change it here too.
//
// This is the same job the webhook source does: whatever the source calls its
// fields, one standard lead comes out.

return $input.all().map((item) => {
  const form = item.json || {};
  const get = (label) => String(form[label] ?? '').trim();

  const fullName = get('Your name');
  const [firstName, ...rest] = fullName.split(/\s+/);

  return {
    json: {
      lead: {
        lead_id: `lead_${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`,
        received_at: new Date().toISOString(),
        source: 'form',
        source_detail: 'website-contact',
        first_name: firstName || '',
        last_name: rest.join(' '),
        email: get('Work email').toLowerCase(),
        phone: get('Phone'),
        company: get('Company'),
        website: '',
        office_size_sqft: Number(String(get('Roughly how big is the space? (sq ft)')).replace(/[^0-9.]/g, '')) || null,
        cleaning_frequency: get('How often do you need cleaning?'),
        city: get('City'),
        message: get('What do you need?'),
        raw: form,
      },
    },
  };
});
